package org.efootballrevival.runtimeprobe;
import android.widget.TextView;import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;import android.content.Context;
public final class EnglishDisplay {
 private static Map<String,String> words;private static Pattern pattern;
 private static synchronized void init(Context c){if(words!=null)return;words=new HashMap<String,String>();try{InputStream in=c.getAssets().open("editor-english.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();JSONObject j=new JSONObject(new String(out.toByteArray(),"UTF-8"));ArrayList<String> keys=new ArrayList<String>();Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();if(Pattern.compile("[\\u3400-\\u9fff]").matcher(k).find()){keys.add(k);words.put(k,j.getString(k));}}Collections.sort(keys,new Comparator<String>(){public int compare(String a,String b){return b.length()-a.length();}});StringBuilder re=new StringBuilder();for(String k:keys){if(re.length()>0)re.append('|');re.append(Pattern.quote(k));}pattern=Pattern.compile(re.toString());}catch(Exception e){pattern=null;}}
 public static void setText(TextView v,CharSequence s){String text=s==null?"":UiStrings.t(s.toString());if(Pattern.compile("[\\u3400-\\u9fff]").matcher(text).find()){init(v.getContext());if(pattern!=null){Matcher m=pattern.matcher(text);StringBuffer b=new StringBuffer();while(m.find())m.appendReplacement(b,Matcher.quoteReplacement(words.get(m.group())));m.appendTail(b);text=b.toString();}}v.setText(text);}
}
